#pragma once
// Public frozen Vertex, Triangle and TriangleHit layouts are asserted by the
// host which borrows their live device views. The compact instance table has
// the inverse-transpose generated by the same Ocarina matrix implementation.
struct MaterialVertex {
    float position[3], normal[3], uv[4];
};
struct alignas(16) MaterialHit {
    unsigned instance, primitive;
    float2 bary;
};

__device__ __forceinline__ float3 bsdf_apply(const float4 *r,float3 v,bool point) {
    const float w=point?1.f:0.f;
    return make_float3(r[0].x*v.x+r[0].y*v.y+r[0].z*v.z+r[0].w*w,
                       r[1].x*v.x+r[1].y*v.y+r[1].z*v.z+r[1].w*w,
                       r[2].x*v.x+r[2].y*v.y+r[2].z*v.z+r[2].w*w);
}
__device__ __forceinline__ float3 bsdf_unit(float3 v) {
    const float inv=rsqrtf(v.x*v.x+v.y*v.y+v.z*v.z);
    return make_float3(v.x*inv,v.y*inv,v.z*inv);
}
__device__ __forceinline__ float3 bsdf_load(const float *p) {
    return make_float3(p[0],p[1],p[2]);
}
__device__ __forceinline__ unsigned bsdf_vertex_normal(const MrParams &p,unsigned i,const Observation &g) {
    const auto hit=pointer<const MaterialHit>(p.vertex_frame.hits)[i];
    if(hit.instance!=unsigned(g.surface_key>>32u) || hit.primitive!=g.primitive_id ||
       hit.instance>=p.vertex_frame.instance_count)return 0xffffffffu;
    const auto mesh=pointer<const lfs::denoise::mr_native::MaterialVertexMesh>(p.vertex_frame.meshes)[hit.instance];
    if(mesh.material!=unsigned(g.surface_key) || hit.primitive>=mesh.triangle_count)return 0xffffffffu;
    const auto tri=pointer<const uint3>(mesh.triangles)[hit.primitive];
    if(tri.x>=mesh.vertex_count || tri.y>=mesh.vertex_count || tri.z>=mesh.vertex_count)return 0xffffffffu;
    const auto *vertex=pointer<const MaterialVertex>(mesh.vertices);
    const auto &a=vertex[tri.x],&b=vertex[tri.y],&c=vertex[tri.z];
    const float u=hit.bary.x,v=hit.bary.y,w=1.f-u-v;
    float3 n=make_float3(u*a.normal[0]+v*b.normal[0]+w*c.normal[0],
                         u*a.normal[1]+v*b.normal[1]+w*c.normal[1],
                         u*a.normal[2]+v*b.normal[2]+w*c.normal[2]);
    const auto *transform=pointer<const float4>(p.vertex_frame.transforms)+6u*hit.instance;
    if(n.x!=0.f || n.y!=0.f || n.z!=0.f) {
        n=bsdf_apply(transform+3,n,false);
    } else {
        const auto p2=bsdf_apply(transform,bsdf_load(c.position),true);
        const auto d0=subtract(bsdf_apply(transform,bsdf_load(a.position),true),p2);
        const auto d1=subtract(bsdf_apply(transform,bsdf_load(b.position),true),p2);
        n=make_float3(d0.y*d1.z-d0.z*d1.y,d0.z*d1.x-d0.x*d1.z,d0.x*d1.y-d0.y*d1.x);
    }
    const unsigned word=pack_normal(bsdf_unit(bsdf_unit(n)));
    return word==0xffffffffu?0u:word;
}
